<div class="d-flex justify-content-between align-items-center mb-4"><h1 class="h3 mb-0">Categories</h1><a class="btn btn-success" href="<?= url_to('admin.categories.create') ?>">Add Category</a></div>
<form class="card border-0 p-3 mb-3" method="get"><div class="row g-2"><div class="col-md-5"><input class="form-control" name="q" value="<?= esc($q) ?>" placeholder="Search categories"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['active','inactive'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select class="form-select" name="parent_id"><option value="">All parents</option><?php foreach($parents as $p): ?><option value="<?= $p['id'] ?>" <?= $parent===$p['id']?'selected':'' ?>><?= esc($p['name']) ?></option><?php endforeach ?></select></div><div class="col-md-1"><button class="btn btn-success w-100">Go</button></div></div></form>
<div class="card border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Image</th><th>Name</th><th>Parent</th><th>Products</th><th>Status</th><th>Sort</th><th>Action</th></tr></thead><tbody><?php foreach($categories as $c): ?><tr><td><?php if($c['image']): ?><img src="<?= base_url($c['image']) ?>" width="48" height="48" class="rounded object-fit-cover" alt=""><?php else: ?>—<?php endif ?></td><td><strong><?= esc($c['name']) ?></strong><div class="small text-muted"><?= esc($c['slug']) ?></div></td><td><?= esc($c['parent_name']??'—') ?></td><td><?= $c['products_count'] ?></td><td><span class="badge text-bg-<?= $c['status']==='active'?'success':'secondary' ?>"><?= ucfirst($c['status']) ?></span></td><td><?= $c['sort_order'] ?></td><td><a class="btn btn-sm btn-outline-primary" href="<?= url_to('admin.categories.edit',$c['id']) ?>">Edit</a> <form class="d-inline" method="post" action="<?= site_url('admin/categories/'.$c['id'].'/delete') ?>" onsubmit="return confirm('Delete this category?')"><?= csrf_field() ?><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach ?><?php if(!$categories): ?><tr><td colspan="7" class="text-center text-muted py-4">No categories found.</td></tr><?php endif ?></tbody></table></div></div><div class="mt-3"><?= $pager->links() ?></div>
